fn sid(p:Handle)->Result<Vec<u8>>{need(!p.is_null()&&unsafe{IsValidSid(p)}!=0,"original security SID")?;let n=unsafe{GetLengthSid(p)} as usize;need((8..=68).contains(&n),"security SID extent")?;Ok(unsafe{std::slice::from_raw_parts(p.cast(),n)}.to_vec())}
/// Captured owner/DACL from the original object; allocation gets one checked
/// release even when semantic validation fails. Object kind is explicit.
pub(crate) fn security(h:Handle,kind:i32,user:&[u8],exact_pipe:bool)->Result<(Vec<u8>,[u8;32])>{
 let mut allocation=Owned::empty(Kind::SecurityAllocation);let(mut owner,mut acl,mut sd)=(null_mut(),null_mut(),null_mut());let code=unsafe{GetSecurityInfo(h,kind,5,&mut owner,null_mut(),&mut acl,null_mut(),&mut sd)};let attached=if !sd.is_null(){allocation.attach(sd)}else{Ok(())};
 let result:Result<(Vec<u8>,[u8;32])>=(||{attached?;need(code==0&&!sd.is_null()&&!acl.is_null(),"original native security acquisition")?;let n=unsafe{GetSecurityDescriptorLength(sd)};need((20..=65535).contains(&n),"original descriptor bound")?;let own=sid(owner)?;let head=unsafe{std::slice::from_raw_parts(acl.cast::<u8>(),8)};let bytes=u16::from_le_bytes([head[2],head[3]]) as usize;let count=u16::from_le_bytes([head[4],head[5]]) as usize;need((8..=65535).contains(&bytes)&&count<=256&&count<=(bytes-8)/4,"original ACL bound")?;let raw=unsafe{std::slice::from_raw_parts(acl.cast::<u8>(),bytes)};
  if exact_pipe{let(mut control,mut revision)=(0u16,0u32);need(unsafe{GetSecurityDescriptorControl(sd,&mut control,&mut revision)}!=0&&control&0x1000!=0&&own==user&&count==2,"protected owner exact two ACEs")?;let mut principals=Vec::new();for index in 0..2{let mut ace=null_mut();need(unsafe{GetAce(acl,index,&mut ace)}!=0&&!ace.is_null(),"exact original ACE acquisition")?;let offset=(ace as usize).checked_sub(acl as usize).ok_or("ACE range")?;need(offset>=8&&offset+8<=bytes,"ACE header range")?;let n=u16::from_le_bytes([raw[offset+2],raw[offset+3]]) as usize;need(n>=16&&offset+n<=bytes&&raw[offset]==0&&raw[offset+1]==0&&u32::from_le_bytes(raw[offset+4..offset+8].try_into().unwrap())==0x1f01ff,"exact noninherited allowed full pipe rights")?;let principal=sid(unsafe{ace.cast::<u8>().add(8)}.cast())?;need(principal.len()+8==n,"exact ACE SID size")?;principals.push(principal)}let system=[1,1,0,0,0,0,0,5,18,0,0,0];need(principals.iter().filter(|p|p.as_slice()==user).count()==1&&principals.iter().filter(|p|p.as_slice()==system).count()==1,"only current TEST owner and SYSTEM")?;}
  Ok((own,crate::hash(raw)))})();let close=allocation.close_checked();match(result,close){(Ok(v),Ok(()))=>Ok(v),(a,b)=>Err(format!("original security={a:?}; consuming close={b:?}"))}
}
pub(crate) struct Channel{pipe:Owned,deadline:Instant,user:Vec<u8>,name:String,server:bool,operation_phase:bool}
impl Channel{
 pub(crate) fn server(name:String,user:&[u8])->Result<Self>{let mut value=Self{pipe:Owned::empty(Kind::LocalPipe),deadline:Instant::now()+Duration::from_secs(30),user:user.to_vec(),name,server:true,operation_phase:false};let mut allocation=Owned::empty(Kind::SecurityAllocation);let sddl=format!("O:{}D:P(A;;0x001f01ff;;;SY)(A;;0x001f01ff;;;{})",sid_text(),sid_text());let mut sd=null_mut();let good=unsafe{ConvertStringSecurityDescriptorToSecurityDescriptorW(wide(&sddl).as_ptr(),1,&mut sd,null_mut())}!=0;let attach=if !sd.is_null(){allocation.attach(sd)}else{Ok(())};let operation:Result<()>=(||{attach?;need(good&&!sd.is_null(),"source-owned local descriptor creation")?;let a=Attributes{length:size_of::<Attributes>() as u32,descriptor:sd,inherit:0};value.pipe.attach(unsafe{CreateNamedPipeW(wide(&value.name).as_ptr(),3|0x80000,4|2|1|8,1,2048,2048,0,&a)})?;value.security()?;Ok(())})();let close=allocation.close_checked();match(operation,close){(Ok(()),Ok(()))=>Ok(value),(a,b)=>{let pipeclose=value.close_checked();Err(format!("server acquisition={a:?}; descriptor={b:?}; pipe={pipeclose:?}"))}}
 }
 pub(crate) fn client(name:String,user:&[u8])->Result<Self>{need(name.starts_with("\\\\.\\pipe\\Mutiny-NativeRoot-Startup-")&&name.len()<=256&&!name.contains('\0'),"literal scoped original startup route")?;let mut value=Self{pipe:Owned::empty(Kind::LocalPipe),deadline:Instant::now()+Duration::from_secs(30),user:user.to_vec(),name,server:false,operation_phase:false};value.pipe.attach(unsafe{CreateFileW(wide(&value.name).as_ptr(),0xc0000000,0,null_mut(),3,0,null_mut())})?;let mode=2|1;need(unsafe{SetNamedPipeHandleState(value.pipe.raw()?,&mode,null_mut(),null_mut())}!=0,"actual client message NOWAIT state")?;value.security()?;Ok(value)}
 pub(crate) fn begin_startup_operation(&mut self)->Result<()>{self.live()?;need(!self.operation_phase&&self.name.starts_with(r"\\.\pipe\Mutiny-NativeRoot-Startup-"),"one authenticated startup operation phase, never RootLaunch protocol")?;self.operation_phase=true;self.deadline=Instant::now()+Duration::from_secs(600);Ok(())}
 pub(crate) fn name(&self)->&str{&self.name}
 fn live(&self)->Result<()>{owned::known()?;need(Instant::now()<self.deadline,"finite original channel deadline")}
 pub(crate) fn security(&self)->Result<()>{self.live()?;let mut flags=0;need(unsafe{GetFileType(self.pipe.raw()?)}==3&&unsafe{GetNamedPipeInfo(self.pipe.raw()?,&mut flags,null_mut(),null_mut(),null_mut())}!=0&&flags&4!=0&&((flags&1!=0)==self.server),"exact native pipe object kind/end/message type")?;security(self.pipe.raw()?,6,&self.user,true)?;Ok(())}
 pub(crate) fn connect(&self,require:impl Fn()->Result<()>)->Result<()>{loop{self.live()?;require()?;let good=unsafe{ConnectNamedPipe(self.pipe.raw()?,null_mut())}!=0;let code=if good{0}else{unsafe{owned::GetLastError()}};if !good&&code==535{break}need(good||code==536,"finite local pipe connect")?;thread::sleep(Duration::from_millis(5))}self.security()}
 pub(crate) fn require_child(&self,job:&Job)->Result<()>{self.live()?;let(facts,_)=job.peer()?;let(mut pid,mut session)=(0,0);need(unsafe{GetNamedPipeClientProcessId(self.pipe.raw()?,&mut pid)}!=0&&unsafe{GetNamedPipeClientSessionId(self.pipe.raw()?,&mut session)}!=0&&pid==facts.pid&&session==facts.session,"OS original client PID/session differs")?;job.peer()?;self.security()}
 pub(crate) fn write(&self,payload:&[u8],require:impl Fn()->Result<()>)->Result<()>{need(!payload.is_empty()&&payload.len()<=1020,"fixed bounded frame")?;let mut message=Vec::with_capacity(payload.len()+4);message.extend_from_slice(&(payload.len() as u32).to_le_bytes());message.extend_from_slice(payload);loop{self.live()?;require()?;let mut n=0;let good=unsafe{WriteFile(self.pipe.raw()?,message.as_ptr().cast(),message.len() as u32,&mut n,null_mut())}!=0;let error=if good{0}else{unsafe{owned::GetLastError()}};require()?;if good&&n as usize==message.len(){return Ok(())}if good&&n==0{thread::sleep(Duration::from_millis(5));continue}owned::mark_unknown();return Err(format!("original partial/write {error}/{n}; lost acknowledgement UNKNOWN"))}}
 pub(crate) fn read(&self,require:impl Fn()->Result<()>)->Result<Vec<u8>>{let mut message=[0u8;1024];loop{self.live()?;require()?;let mut n=0;let good=unsafe{ReadFile(self.pipe.raw()?,message.as_mut_ptr().cast(),1024,&mut n,null_mut())}!=0;let error=if good{0}else{unsafe{owned::GetLastError()}};require()?;if good{need((5..=1024).contains(&n)&&u32::from_le_bytes(message[..4].try_into().unwrap())==n-4,"whole original message frame")?;return Ok(message[4..n as usize].to_vec())}if error==232&&n==0{thread::sleep(Duration::from_millis(5));continue}owned::mark_unknown();return Err(format!("original EOF/partial/read {error}/{n}; no retry"))}}
 pub(crate) fn send(&self,header:&str,payload:&[u8],require:impl Fn()->Result<()>)->Result<()>{need(!payload.is_empty()&&payload.len()<=67108864,"aggregate capsule before framing")?;self.write(format!("{header} {}",payload.len()).as_bytes(),&require)?;for chunk in payload.chunks(1020){self.write(chunk,&require)?}Ok(())}
 pub(crate) fn receive(&self,header:&str,cap:usize,require:impl Fn()->Result<()>)->Result<Vec<u8>>{let head=String::from_utf8(self.read(&require)?).map_err(|_|"ASCII capsule header")?;let n=head.strip_prefix(&format!("{header} ")).ok_or("fixed capsule header")?.parse::<usize>().map_err(|_|"capsule size")?;need(n>0&&n<=cap&&head==format!("{header} {n}"),"canonical whole capsule size")?;let mut b=Vec::with_capacity(n);while b.len()<n{let part=self.read(&require)?;need(part.len()==1020.min(n-b.len()),"exact bounded capsule chunk")?;b.extend(part)}Ok(b)}
 pub(crate) fn close_checked(&mut self)->Result<()>{self.pipe.close_checked()}
 pub(crate) fn quarantine(&mut self){self.pipe.quarantine()}
}
pub(crate) struct Parent{process:Owned,facts:OwnTokenFacts,image:String}
impl Parent{
 pub(crate) fn acquire(channel:&Channel,image:&str)->Result<Self>{let(mut pid,mut session)=(0,0);need(unsafe{GetNamedPipeServerProcessId(channel.pipe.raw()?,&mut pid)}!=0&&unsafe{GetNamedPipeServerSessionId(channel.pipe.raw()?,&mut session)}!=0&&pid>0,"OS original startup server identity")?;let mut process=Owned::empty(Kind::Process);process.attach(unsafe{OpenProcess(0x1000|0x100000,0,pid)})?;let(mut b,mut e,mut k,mut u)=(Time::default(),Time::default(),Time::default(),Time::default());need(unsafe{GetProcessTimes(process.raw()?,&mut b,&mut e,&mut k,&mut u)}!=0,"original startup server creation")?;let start=(b.high as u64)<<32|b.low as u64;let facts=unsafe{own_native_token::observe_selected_peer(process.raw()?,pid,start)}?;need(session==facts.session,"original server session")?;let p=Self{process,facts,image:image.into()};p.require(channel)?;Ok(p)}
 pub(crate) fn require(&self,c:&Channel)->Result<()>{c.security()?;let(mut pid,mut session)=(0,0);need(unsafe{GetNamedPipeServerProcessId(c.pipe.raw()?,&mut pid)}!=0&&unsafe{GetNamedPipeServerSessionId(c.pipe.raw()?,&mut session)}!=0&&pid==self.facts.pid&&session==self.facts.session&&unsafe{WaitForSingleObject(self.process.raw()?,0)}==258,"same original live server")?;let mut name=[0u16;4097];let mut n=name.len() as u32;need(unsafe{QueryFullProcessImageNameW(self.process.raw()?,0,name.as_mut_ptr(),&mut n)}!=0&&n>0&&(n as usize)<name.len()&&String::from_utf16(&name[..n as usize]).map_err(|_|"original parent image UTF16")?==self.image,"same actual native original server image")?;need(unsafe{own_native_token::observe_selected_peer(self.process.raw()?,self.facts.pid,self.facts.process_start_filetime)}?==self.facts,"original parent full token unchanged")}
 pub(crate) fn facts(&self)->&OwnTokenFacts{&self.facts}
 pub(crate) fn close_checked(&mut self)->Result<()>{self.process.close_checked()}
 pub(crate) fn quarantine(&mut self){self.process.quarantine()}
}
